# First quick exact k-mer candidate + global DP in C-like numpy for one query.
def global_dp(a,b):
 n,m=len(a),len(b)
 # full DP matrix int16
 prev=np.full(m+1,0,dtype=np.int32);prev[np.arange(1,m+1)]=np.arange(1,m+1)
 for i,x in enumerate(a,1):
  cur=np.empty(m+1,dtype=np.int32);cur[0]=i
  # vectorized min recurrence is tricky; loop
  for j,y in enumerate(b,1):
   cur[j]=min(prev[j]+1,cur[j-1]+1,prev[j-1]+(x!=y))
  prev=cur
 d=prev[m]
 # traceback to get aligned strings
 i,j=n,m; aa=[];bb=[]
 while i>0 or j>0:
  if i>0 and j>0 and a[i-1]==b[j-1] and prev[j]==i-1+(a[i-1]!=b[j-1]):
   aa.append(a[i-1]);bb.append(b[j-1]);i-=1;j-=1
  elif i>0 and j>0 and prev[j]==d:
   aa.append(a[i-1]);bb.append(b[j-1]);i-=1;j-=1
  elif i>0:
   aa.append(a[i-1]);bb.append('-');i-=1
  else:
