 else:seq.append(line)
if name is not None:rec.append((name,''.join(seq)))
assert len(rec)==43
# Final counts
samples=[f'S{i:02d}' for i in range(1,12)]
with open('/task/output/work/counts43.tsv') as f:counts=list(csv.DictReader(f,delimiter='\t'))
cm={r['asv_id']:r for r in counts}
assert set(cm)=={x[0] for x in rec}
# taxonomy from parsed USEARCH result, plus explicit unclassified for ASV013/016
hits={}
for line in open('/task/output/work/vs/centers43.ref.blast6.tsv'):
 x=line.split();hits.setdefault(x[0].split(';')[0],[]).append((float(x[2]),x[1]))
tax={}
for l in open('/task/input/reference_taxonomy.tsv'):
 x=l.rstrip().split('\t')
 if len(x)>1:tax[x[0]]=x[1]
genus={}
for aid,_ in rec:
 if aid not in hits:
  genus[aid]='Unclassified';continue
 best=max(x[0] for x in hits[aid]); ties=[x[1] for x in hits[aid] if x[0]==best]; gs=sorted(set(tax.get(r,'Unclassified') for r in ties))
 genus[aid]=gs[0] if best>=97 and len(gs)==1 else 'Unclassified'
# contaminants identified from extraction blank enrichment / reagent provenance
contam=['ASV003','ASV005','ASV007','ASV009','ASV015']
# Write asv.fasta
with open(out/'asv.fasta','w') as f:
 for aid,seq in rec:
  assert set(seq)<=set('ACGT') and seq
  f.write(f'>{aid}\n{seq}\n')
# Write table
with open(out/'asv_table.tsv','w') as f:
 f.write('asv_id\t'+'\t'.join(samples)+'\n')
 for aid,seq in rec:
  vals=[]
  for s in samples:
   v=int(cm[aid][s]);assert v>=0;vals.append(str(v))
  f.write(aid+'\t'+'\t'.join(vals)+'\n')
# taxonomy
with open(out/'taxonomy.tsv','w') as f:
 f.write('asv_id\tgenus\n')
 for aid,seq in rec:f.write(f'{aid}\t{genus[aid]}\n')
# contaminants
with open(out/'contaminants.txt','w') as f:
 f.write('asv_id\n')
 for aid in contam:f.write(aid+'\n')
print('wrote',len(rec),'ASVs; total counts',sum(int(cm[a][s]) for a,_ in rec for s in samples))
print('taxonomy',genus)
